import{c as e,Z as s,Q as i,j as h,m as a,g as l,n as d,o,av as n}from"./chunks/framework.rWdQudnF.js";const M=JSON.parse('{"title":"架构师-备考 综合知识-面向对象-UML建模","description":"","frontmatter":{"title":"架构师-备考 综合知识-面向对象-UML建模"},"headers":[],"relativePath":"综合知识/面向对象/UML建模.md","filePath":"综合知识/面向对象/UML建模.md","lastUpdated":null}'),p={name:"综合知识/面向对象/UML建模.md"};function g(b,t,c,u,m,q){const r=s("font");return i(),h("div",null,[t[3]||(t[3]=a('<h3 id="uml-概述" tabindex="-1">UML 概述 <a class="header-anchor" href="#uml-概述" aria-label="Permalink to &quot;UML 概述&quot;">​</a></h3><blockquote><p>UML（统一建模语言）是<strong>可视化的建模语言，而非程序设计语言</strong>，支持从需求分析开始的软件开发全过程。</p></blockquote><h3 id="三大结构" tabindex="-1">三大结构 <a class="header-anchor" href="#三大结构" aria-label="Permalink to &quot;三大结构&quot;">​</a></h3><p><strong>UML 三大结构：</strong></p><table tabindex="0"><thead><tr><th>组成部分</th><th>说明</th></tr></thead><tbody><tr><td><strong>构造块</strong></td><td>事物（thing）+ 关系（relationship）+ 图（diagram）</td></tr><tr><td><strong>规则</strong></td><td>构造块如何放在一起的规定</td></tr><tr><td><strong>公共机制</strong></td><td>达到特定目标的公共 UML 方法</td></tr></tbody></table><h3 id="事物" tabindex="-1">事物 <a class="header-anchor" href="#事物" aria-label="Permalink to &quot;事物&quot;">​</a></h3><ul><li>结构事物：模型的静态部分，如类、接口、用例、构件等：</li><li>行为事物：模型的动态部分，如交互、活动、状态机：</li><li>分组事物：模型的组织部分，如包；</li><li>注释事物：模型的解释部分，依附于一个元素或一组元素之上对其进行约束或解释的简单符号。</li></ul><hr><h3 id="关系" tabindex="-1">关系 <a class="header-anchor" href="#关系" aria-label="Permalink to &quot;关系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>关系</th><th>说明</th><th>UML 表示</th></tr></thead><tbody><tr><td><strong>依赖（Dependency）</strong></td><td>一个事物发生变化会影响另一个事物，短暂非持久</td><td>虚线箭头</td></tr><tr><td><strong>关联（Association）</strong></td><td>类之间的某种联系，通常是双向的</td><td>实线</td></tr><tr><td><strong>泛化（Generalization）</strong></td><td>一般与特殊的关系（继承）</td><td>实线空心三角箭头</td></tr><tr><td><strong>实现（Realization）</strong></td><td>类实现接口</td><td>虚线空心三角箭头</td></tr></tbody></table><p><strong>聚集 vs 组合（关联的特殊类型）：</strong></p><table tabindex="0"><thead><tr><th>对比</th><th>聚集（Aggregation）</th><th>组合（Composition）</th></tr></thead><tbody><tr><td>关系强度</td><td>较弱</td><td>较强</td></tr><tr><td>整体-部分</td><td>部分可脱离整体独立存在</td><td>部分<strong>不能脱离整体</strong>单独存在</td></tr><tr><td>示例</td><td>大学→学生（学生可独立存在）</td><td>大学→系（系不能脱离大学）</td></tr></tbody></table><blockquote><p>口诀：<strong>聚集整体散，组合整体断。</strong></p></blockquote><hr><p>关系 UML 图形代号</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517231621.png" alt="image.png"></p><hr><h4 id="聚合" tabindex="-1">聚合 <a class="header-anchor" href="#聚合" aria-label="Permalink to &quot;聚合&quot;">​</a></h4><hr><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260522155929.png" alt="image.png"></p><hr><hr><h3 id="用例建模" tabindex="-1">用例建模 <a class="header-anchor" href="#用例建模" aria-label="Permalink to &quot;用例建模&quot;">​</a></h3><p><strong>参与者（Actor）</strong>：与系统交互的外部实体，可以是<strong>人、外部系统、时间、设备</strong>（如打印机）。</p><h4 id="uml-图关系" tabindex="-1">UML 图关系 <a class="header-anchor" href="#uml-图关系" aria-label="Permalink to &quot;UML 图关系&quot;">​</a></h4>',25)),l("p",null,[t[1]||(t[1]=d("用例关系包括：",-1)),o(r,{color:"#ff0000"},{default:n(()=>[...t[0]||(t[0]=[d("包含关系、扩展关系、泛化关系",-1)])]),_:1})]),t[4]||(t[4]=a('<p><strong>用例关系三种类型：</strong></p><table tabindex="0"><thead><tr><th>关系</th><th>说明</th><th>典型场景</th></tr></thead><tbody><tr><td><strong>包含（Include）</strong></td><td>一个用例<strong>无条件</strong>使用另一个用例的行为</td><td>注册课程<strong>必先</strong>登录系统</td></tr><tr><td><strong>扩展（Extend）</strong></td><td>一个用例在<strong>特定条件下</strong>扩展另一个用例</td><td>不及格<strong>才参加</strong>补考</td></tr><tr><td><strong>泛化（Generalization）</strong></td><td>用例之间的继承关系</td><td>一般用例→特殊用例</td></tr></tbody></table><hr><h3 id="建模过程" tabindex="-1">建模过程 <a class="header-anchor" href="#建模过程" aria-label="Permalink to &quot;建模过程&quot;">​</a></h3><p>?? 这个 是哪个部分的内容</p><blockquote><p>利用 UML 构建三类模型：</p></blockquote><table tabindex="0"><thead><tr><th>模型</th><th>构建方式</th><th>产物</th></tr></thead><tbody><tr><td><strong>用例模型</strong></td><td>分析需求行为，按 OO 原则划分为用例</td><td>用例图 + 顺序图</td></tr><tr><td><strong>分析模型</strong></td><td>在用例基础上抽象类，明确关系构建类图</td><td>类图 + 领域概念模型</td></tr><tr><td><strong>设计模型</strong></td><td>补充状态图/活动图/协作图等描述内部处理细节</td><td>完整 UML 模型</td></tr></tbody></table><h3 id="uml-图" tabindex="-1">UML 图 <a class="header-anchor" href="#uml-图" aria-label="Permalink to &quot;UML 图&quot;">​</a></h3><p>UML2.0图，书上是13种，实际还包含制品图，一共14种，了解即可，总分类如下：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517231715.png" alt="image.png"></p><h4 id="静态图-描述系统静态结构" tabindex="-1">静态图（描述系统静态结构） <a class="header-anchor" href="#静态图-描述系统静态结构" aria-label="Permalink to &quot;静态图（描述系统静态结构）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>图</th><th>说明</th><th>关键记忆</th></tr></thead><tbody><tr><td><strong>类图</strong></td><td>系统的静态设计视图，展现类及其关系</td><td>最核心的静态图</td></tr><tr><td><strong>对象图</strong></td><td>展现某一时刻一组对象及关系</td><td>类图的实例</td></tr><tr><td><strong>用例图</strong></td><td>描述系统功能需求和参与者</td><td>需求分析阶段使用</td></tr><tr><td><strong>构件图（组件图）</strong></td><td>展现一组构件之间的组织和依赖</td><td>物理实现层面</td></tr><tr><td><strong>部署图</strong></td><td>系统静态部署视图，软硬件映射</td><td>拓扑结构、系统安装</td></tr></tbody></table><h5 id="类图" tabindex="-1">类图 <a class="header-anchor" href="#类图" aria-label="Permalink to &quot;类图&quot;">​</a></h5><p>类图：静态图，为系统的静态设计视图，展现一组对象、接口、协作和它们之间的关系。</p><p>UML类图如下：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517231927.png" alt="image.png"></p><h5 id="对象图" tabindex="-1">对象图 <a class="header-anchor" href="#对象图" aria-label="Permalink to &quot;对象图&quot;">​</a></h5><p>对象图：静态图，展现某一时刻一组对象及它们之间的关系，为类图的某一快照。在没有类图的前提下，对象图就是静态设计视图。如下：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517232030.png" alt="image.png"></p><h5 id="用例图" tabindex="-1">用例图 <a class="header-anchor" href="#用例图" aria-label="Permalink to &quot;用例图&quot;">​</a></h5><p>用例图：静态图，展现了一组用例、参与者以及它们之间的关系。</p><p>用例图中的参与者是人、硬件或其他系统可以扮演的角色；用例是参与者完成的一系列操作，用例之间的关系有扩展、包含、泛化。</p><p>如下：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517232118.png" alt="image.png"></p><h5 id="构件图" tabindex="-1">构件图 <a class="header-anchor" href="#构件图" aria-label="Permalink to &quot;构件图&quot;">​</a></h5><p>构件图（组件图)：静态图，为系统静态实现视图，展现了一组构件之间的组织和依赖。如下：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517232537.png" alt="image.png"></p><h5 id="部署图" tabindex="-1">部署图 <a class="header-anchor" href="#部署图" aria-label="Permalink to &quot;部署图&quot;">​</a></h5><p>部署图：静态图，为系统静态部署视图，部署图物理模块的节点分布。它与构件图相关，通常一个结点包含一个或多个构件。其依赖关系类似于包依赖，因此部署组件之间的依赖是单向的类似于包含关系。</p><p>如下：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517232618.png" alt="image.png"></p><h4 id="动态图-描述系统动态行为" tabindex="-1">动态图（描述系统动态行为） <a class="header-anchor" href="#动态图-描述系统动态行为" aria-label="Permalink to &quot;动态图（描述系统动态行为）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>图</th><th>说明</th><th>关键记忆</th></tr></thead><tbody><tr><td><strong>序列图（顺序图）</strong></td><td>按时间顺序展示对象间交互</td><td>强调<strong>时间顺序</strong></td></tr><tr><td><strong>通信图（协作图）</strong></td><td>强调参加交互的对象的<strong>组织</strong></td><td>强调对象组织结构</td></tr><tr><td><strong>状态图</strong></td><td>描述对象状态及状态转换</td><td>关注对象生命周期</td></tr><tr><td><strong>活动图</strong></td><td>特殊的状态图，描述活动流程</td><td>类似流程图，支持分支汇合</td></tr></tbody></table><blockquote><p>口诀：<strong>类对用构部 = 静态；序通状活 = 动态。序列看时间，通信看组织。</strong></p></blockquote><h5 id="序列图" tabindex="-1">序列图 <a class="header-anchor" href="#序列图" aria-label="Permalink to &quot;序列图&quot;">​</a></h5><p>序列图：即顺序图，动态图，是场景的图形化表示，描述了以时间顺序组织的对象之间的交互活动。</p><ul><li>有同步消息（进行阻塞调用，调用者中止执行，等待控制权返回，需要等待返回消息，用实心三角箭头表示)，</li><li>异步消息（发出消息后继续执行，不引起调用者阻塞，也不等待返回消息，由空心箭头表示)、</li><li>返回消息（由从右到左的虚线箭头表示）三种。</li></ul><p>如下：</p><p>上方的对象对应下方箭头上的的成员和方法。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517232236.png" alt="image.png"></p><h5 id="通信图" tabindex="-1">通信图 <a class="header-anchor" href="#通信图" aria-label="Permalink to &quot;通信图&quot;">​</a></h5><p>通信图：动态图，即协作图，强调参加交互的对象的组织。如下：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517232310.png" alt="image.png"></p><h5 id="状态图" tabindex="-1">状态图 <a class="header-anchor" href="#状态图" aria-label="Permalink to &quot;状态图&quot;">​</a></h5><p>状态图：动态图，展现了一个状态机，描述单个对象在多个用例中的行为，包括简单状态和组合状态。</p><p>转换可以通过事件触发器触发，事件触发后相应的监护条件会进行检查。状态图中转换和状态是两个独立的概念，</p><p>如下：图中方框代表状态，箭头上的代表触发事件，实心圆点为起点和终点。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517232404.png" alt="image.png"></p><h5 id="活动图" tabindex="-1">活动图 <a class="header-anchor" href="#活动图" aria-label="Permalink to &quot;活动图&quot;">​</a></h5><p>活动图：动态图，是一种特殊的状态图，展现了在系统内从一个活动到另一个活动的流程。</p><p>活动的分岔和汇合线是一条水平粗线。牢记下图中并发分岔、并发汇合、监护表达式、分支、流等名词及含义。每个分岔的分支数代表了可同时运行的线程数。</p><p>活动图中能够并行执行的是在一个分岔粗线下的分支上的活动，如下：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517232450.png" alt="image.png"></p><hr><h3 id="uml-5-种视图" tabindex="-1">UML 5 种视图 <a class="header-anchor" href="#uml-5-种视图" aria-label="Permalink to &quot;UML 5 种视图&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517232637.png" alt="image.png"></p><p>4+1 视图模型 ★</p><blockquote><p>4+1 视图从 5 个视角描述软件架构，5 个视图结合才能反映全部内容。</p></blockquote><table tabindex="0"><thead><tr><th>视图</th><th>关注点</th><th>对应 UML 图</th><th>关心者</th></tr></thead><tbody><tr><td><strong>逻辑视图</strong></td><td>系统功能需求</td><td>类图、对象图、状态图</td><td>最终用户</td></tr><tr><td><strong>进程视图</strong></td><td>运行特性、并发/分布/容错</td><td>活动图</td><td>系统集成人员</td></tr><tr><td><strong>实现视图</strong>（开发视图）</td><td>软件模块组织管理</td><td>包图、组件图</td><td>程序员</td></tr><tr><td><strong>部署视图</strong>（物理视图）</td><td>软件→硬件映射、拓扑结构</td><td>部署图</td><td>系统工程师</td></tr><tr><td><strong>用例视图</strong>（场景）</td><td>使4个视图有机联系</td><td>用例图</td><td>分析师/测试人员</td></tr></tbody></table><hr><h3 id="sysml" tabindex="-1">SysML <a class="header-anchor" href="#sysml" aria-label="Permalink to &quot;SysML&quot;">​</a></h3><p>SysML是一种通用图形建模语言，用于指定，分析，设计和验证可能包括硬件，软件，信息，人员，程序和设施的复杂系统。特别是，该语言提供了图形表示，其具有用于建模系统需求，行为，结构和参数的语义基础，用于与其他工程分析模型集成。</p><p>系统建模语言(SysML)已成为基于模型的系统工程(MBSE)应用程序的事实上的标准系统架构建模语言。</p><p>SysML是UML2的一种方言，<strong>它扩展了软件密集型应用程序的统一建模语言(UML)标准</strong>，使其可以成功应用于系统工程应用程序。</p><p>其实提到SysML不得不提另外一个概念：基于模型的系统工程(MBSE)。</p><p>又称基于模型的系统开发(MBSD),是一种系统工程过程范例，强调严格的体系结构建模原则和最佳实践应用于整个系统开发生命周期(SDLC)中的系统工程活动。这些系统工程活动包括但不限于需求分析，功能分析，性能分析，系统设计，贸易研究，系统架构规范以及系统验证和验证。</p><p>与UML相比，<strong>SysML为系统工程师提供了以下优于指定系统的优势</strong>：</p><ul><li>SysML比UML更好地表达系统工程语义（符号解释）。它减少了UML的软件偏差，并为需求管理和性能分析添加了两种新的图表类型：需求图和参数图。</li><li>SysML比UML更小，更容易学习。由于SysML删除了许多以软件为中心和无偿的构造，因此在图表类型(9对13)和总结构中测量的整体语言较小。</li><li>SysML模型管理构造支持模型，视图和视点的规范，这些规范在架构上与1EEE-Std-1471-2000(IEEE推荐的软件密集型系统架构描述实践)保持一致。</li><li>SysML和UML间存在交集，即SysML语言中的部分图是和UML中的相应图是一致的，例如用例图。同时，SysML也有基于UML扩展而来的图，例如活动图。另外，还有一部分图是SysML所特有的，这些图与UML间没有关系，例如需求图。</li></ul>',68)),o(r,{color:"#f79646"},{default:n(()=>[...t[2]||(t[2]=[d("SysML提供了9种图来支持用户进行系统建模。",-1)])]),_:1}),t[5]||(t[5]=a('<p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517233104.png" alt="image.png"></p><h4 id="sysml-图" tabindex="-1">SysML 图 <a class="header-anchor" href="#sysml-图" aria-label="Permalink to &quot;SysML 图&quot;">​</a></h4><p>好的，以下是与图片内容完全一致的表格文本版：</p><table tabindex="0"><thead><tr><th><strong>SYSML 图</strong></th><th><strong>UML 图</strong></th><th><strong>目的</strong></th></tr></thead><tbody><tr><td>活动图（ACT 或行为）：一种行为图，主要关注控制流程，以及输入转化为输出的过程。</td><td>活动图：对系统中任何位置的流进行建模。特别是，描述正常用户交互以及替代和例外的用例中的流程由这些活动图很好地建模。</td><td>[行为图]活动图显示了作为控制和数据流的系统行为。<br>用于功能分析。<br>比较流程图（FBD）和扩展功能流程图（EFFBD），已经在系统工程师中常用。</td></tr><tr><td>模块定义图（BDD 或 bdd）：一种结构图，与内部模块图及参数图互补，用于描述系统的层次以及系统/组件的分类。</td><td>类图：类图表示类，它们的定义和关系问题空间中的类和实体也是解决方案空间中的详细技术实体。定义类的属性和操作包含在此类图中。类图中的关系说明了类如何与其他类交互，协作和继承。类还可以表示关系表，用户界面和控制器。</td><td>[结构图]模块定义图将系统结构显示为组件及其属性，操作和关系。<br>对系统分析和设计很有用。</td></tr><tr><td>内部模块图（IBD 或 ibd）：一种结构图，与模块定义图及参数图互补，通过组件（Parts）、端口、连接器来用于描述系统模块的内部结构。</td><td>复合结构图：在运行时模拟组件或对象行为，显示系统执行期间组件的布局，关系和实例。</td><td>[结构图] 内部模块图显示了系统组件的内部结构，包括其部件和连接器。<br>对系统分析和设计很有用。</td></tr><tr><td>包图（PKG 或 pkg）：一种结构图，以包的形式组织模型间的层级关系。</td><td>包图：表示系统组织的子系统和区域。它还可以模拟包之间的依赖关系，并帮助将业务实体与用户界面，数据库，安全性和管理包分开。</td><td>[结构图]包图显示了如何将模型组织到包，视图和视点中。<br>对模型管理很有用。</td></tr><tr><td>参数图（PAR或par）：SysML特有的图，与模块定义图及参数图互补，用于说明系统的约束。</td><td>（无对应）</td><td>[结构图]参数图显示结构元素之间的参数约束。对性能和定量分析很有用。</td></tr><tr><td>需求图（REQ或req）：用于表述文字化的需求、需求间的关系，以及与之存在满足、验证等关系的其他模型元素。</td><td>（无对应）</td><td>[需求图]需求图显示了系统需求及其与其他元素的关系。<br>适用于需求工程，包括需求验证和确认（V&amp;V）。<br>SysML还包含了分配关系的表述，包括功能到组件的分配、软件到硬件的分配以及逻辑到物理的分配。</td></tr><tr><td>序列图（SD或SD）：一种行为图，主要关注并精确描述系统内部不同模块间的交互。</td><td>序列图：根据对象的时间轴模拟对象之间的交互。对象可以在这些图上具体显示，也可以是属于类的匿名对象。</td><td>[行为图]序列图显示系统行为作为系统组件之间的交互。<br>对系统分析和设计很有用。</td></tr><tr><td>状态机图（STM或stm）：一种行为图，主要关注系统内部模块的一系列状态以及在事件触发下的不同状态间的转换。</td><td>状态机图：显示内存中对象的运行时生命周期。这样的生命周期包括对象的所有状态以及状态改变的条件。</td><td>[行为图]状态机图将系统行为显示为组件或交互响应事件时所经历的状态序列。<br>对系统设计和模拟/代码生成很有用。</td></tr><tr><td>用例图（UC或uc）：一种黑盒视图，是系统功能的高层描述，用于表达系统执行的用例以及引起系统执行行为的参与者。</td><td>用例图：从用户的角度提供系统或业务流程功能的概述。用户“使用”系统的方式是创建用例图的起点。</td><td>[行为图]用例图将系统功能需求显示为对系统用户有意义的事务。<br>用于指定功能要求。（注意潜在的语义重叠与需求图中指定的功能需求。）</td></tr></tbody></table><p>简述版本</p><table tabindex="0"><thead><tr><th>SysML 图</th><th>UML 图</th><th>目的</th></tr></thead><tbody><tr><td>活动图（ACT 或行为图）</td><td>活动图</td><td><strong>[行为图]</strong> 活动图显示了作为控制和数据流的系统行为。用于功能分析。比较流程图（FBD）和扩展功能流程图（EFFBD），已经在系统工程师中常用。</td></tr><tr><td>模块定义图（BDD 或 bdd）</td><td>类图</td><td><strong>[结构图]</strong> 模块定义图将系统结构显示为组件及其属性、操作和关系。对系统分析和设计很有用。</td></tr><tr><td>内部模块图（IBD 或 ibd）</td><td>复合结构图</td><td><strong>[结构图]</strong> 内部模块图显示了系统组件的内部结构，包括其部件和连接器。对系统分析和设计很有用。</td></tr><tr><td>包图（PKG 或 pkg）</td><td>包图</td><td><strong>[结构图]</strong> 包图显示了如何将模型组织到包、视图和视点中。对模型管理很有用。</td></tr><tr><td>参数图（PAR 或 par）</td><td><em>（SysML 特有）</em></td><td><strong>[结构图]</strong> 参数图显示结构元素之间的参数约束。对性能和定量分析很有用。</td></tr><tr><td>需求图（REQ 或 req）</td><td><em>（SysML 特有）</em></td><td><strong>[需求图]</strong> 需求图显示了系统需求及其与其他元素的关系。适用于需求工程，包括需求验证和确认（V&amp;V）。SysML 还包含了分配关系的表述，包括功能到组件的分配、软件到硬件的分配以及逻辑到物理的分配。</td></tr><tr><td>序列图（SD 或 sd）</td><td>序列图</td><td><strong>[行为图]</strong> 序列图显示系统行为作为系统组件之间的交互。对系统分析和设计很有用。</td></tr><tr><td>状态机图（STM 或 stm）</td><td>状态机图</td><td><strong>[行为图]</strong> 状态机图将系统行为显示为组件或交互响应事件时所经历的状态序列。对系统设计和模拟/代码生成很有用。</td></tr><tr><td>用例图（UC 或 uc）</td><td>用例图</td><td><strong>[行为图]</strong> 用例图将系统功能需求显示为对系统用户有意义的事务。用于指定功能需求。（注意潜在的语义重叠与需求图中指定的功能需求。）</td></tr></tbody></table><p>需求图：标准SysML需求包括用于指定其唯一性的标识符和需求文本两个属性，如图所示。其他属性（例如，验证状态，优先级等）也可以由用户指定。</p><h4 id="需求关系" tabindex="-1">需求关系 <a class="header-anchor" href="#需求关系" aria-label="Permalink to &quot;需求关系&quot;">​</a></h4><p>SysML规定了七个需求关系</p><h5 id="_1-复合关系" tabindex="-1">1) 复合关系 <a class="header-anchor" href="#_1-复合关系" aria-label="Permalink to &quot;1) 复合关系&quot;">​</a></h5><p>复合需求可以包含需求层次结构中的子需求。复合需求可以声明系统应执行A和B,可以将其分解为系统应执行A和系统应进行B的子需求</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517233546.png" alt="image.png"></p><h5 id="_2-派生关系" tabindex="-1">2）派生关系 <a class="header-anchor" href="#_2-派生关系" aria-label="Permalink to &quot;2）派生关系&quot;">​</a></h5><p>派生关系：派生的需求通常对应于系统层次结构下一级的需求。一个简单的例子是车辆加速需求，该需求被分析以导出发动机动力等方面的需求</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517233630.png" alt="image.png"></p><h5 id="_3-细化关系" tabindex="-1">3) 细化关系 <a class="header-anchor" href="#_3-细化关系" aria-label="Permalink to &quot;3) 细化关系&quot;">​</a></h5><p>细化关系：细化关系可用于描述如何使用模型元素或元素集进一步细化需求。例如，可以使用用例或活动图来细化基于文本的功能需求</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517233704.png" alt="image.png"></p><h5 id="_4-满足关系" tabindex="-1">4) 满足关系 <a class="header-anchor" href="#_4-满足关系" aria-label="Permalink to &quot;4) 满足关系&quot;">​</a></h5><p>满足关系：满足关系描述了设计或实现模型如何满足一个或多个需求。然后，系统建模者可以指定旨在满足要求的系统设计元素</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517233750.png" alt="image.png"></p><h5 id="_5-验证关系" tabindex="-1">5) 验证关系 <a class="header-anchor" href="#_5-验证关系" aria-label="Permalink to &quot;5) 验证关系&quot;">​</a></h5><p>验证关系：验证关系定义了测试用例或其他模型元素如何验证需求。在SysML中，测试用例或其他元素可以用作表示任何标准检验方法的通用机制，分析，演示或测试。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517233826.png" alt="image.png"></p><h5 id="_6-复制关系" tabindex="-1">6) 复制关系 <a class="header-anchor" href="#_6-复制关系" aria-label="Permalink to &quot;6) 复制关系&quot;">​</a></h5><h5 id="_7-追溯关系" tabindex="-1">7) 追溯关系 <a class="header-anchor" href="#_7-追溯关系" aria-label="Permalink to &quot;7) 追溯关系&quot;">​</a></h5><h4 id="模块定义图bdd和内部模块图ibd" tabindex="-1">模块定义图BDD和内部模块图IBD <a class="header-anchor" href="#模块定义图bdd和内部模块图ibd" aria-label="Permalink to &quot;模块定义图BDD和内部模块图IBD&quot;">​</a></h4><p>创建 IBD是为了指定单个模块的内部结构。和BDD一样，IBD是系统或者系统一个组成部分的静态（结构化）视图。和BDD不同的是，IBD不会显示模块，它会显示对模块的使用一一也就是在 IBD头部命名的模块的组成部分属性和引用属性。</p><p>在BDD中也可以显示组成部分属性和引用属性一一或者是作为模块分隔框中的字符串，或者是作为关联一端的角色名称。但是 IBD可以表达在BDD中无法表达的信息：组成部分属性和引用属性之间的连接：在连接之间流动的事件、能量和数据的类型：以及通过连接提供和请求的服务。</p><p>IBD会表达模块的组成部分必须如何组合才能够创建有效实例。它还会显示模块的实例必须如何与外部实体（引用属性）连接，以在整体上创建系统的有效实例。</p><h4 id="参数图" tabindex="-1">参数图 <a class="header-anchor" href="#参数图" aria-label="Permalink to &quot;参数图&quot;">​</a></h4><p>略</p><hr>',33))])}const L=e(p,[["render",g]]);export{M as __pageData,L as default};
